using UnityEngine;
using UnityEngine.UI;
using Sizing=EscapeFromBorderlands.Client.BackpackLayoutSizing;
int cases=0,checks=0,failures=0;
void Check(bool condition,string name){checks++;if(!condition)throw new Exception(name);}
void Eq(float a,float b,string name)=>Check(Math.Abs(a-b)<.001f,$"{name}: {a}!={b}");
void Run(string name,Action action){cases++;LayoutRebuilder.Dirty.Clear();try{action();Console.WriteLine("PASS "+name);}catch(Exception ex){failures++;Console.WriteLine("FAIL "+name+": "+ex);}}
RectTransform Rect(float width=0,float height=0,Transform? parent=null){var r=new GameObject().transform;r.parent=parent;r.sizeDelta=new(width,height);return r;}
LayoutElement Element(RectTransform r)=>(LayoutElement)r.gameObject.GetComponent(typeof(LayoutElement))!;
float PreferredHeight(RectTransform r){var e=r.gameObject.GetComponent(typeof(LayoutElement)) as LayoutElement;return e is {enabled:true,ignoreLayout:false}?Math.Max(e.minHeight,e.preferredHeight):0;}
Run("A manually positioned grid with no provider reserves its complete inventory row",()=>{var root=Rect();Eq(PreferredHeight(root),0,"native layout sees no height before repair");Sizing.Apply(root,442,834);var e=Element(root);Check(e!=null,"provider is created");Eq(e!.minHeight,834,"minimum includes lower pockets");Eq(e.preferredHeight,834,"preferred includes lower pockets");Eq(e.minWidth,442,"all columns reserved");Eq(e.preferredWidth,442,"preferred width is exported");Eq(root.Height,834,"actual root height");Eq(root.Width,442,"actual root width");Eq(Math.Max(168,PreferredHeight(root))+8,842,"pouch begins below complete backpack");});
Run("Existing disabled or ignored providers are repaired and reused",()=>{var root=Rect();var e=(LayoutElement)root.gameObject.AddComponent(typeof(LayoutElement));e.enabled=false;e.ignoreLayout=true;e.minWidth=50;e.preferredWidth=50;e.minHeight=50;e.preferredHeight=50;e.flexibleHeight=1;e.flexibleWidth=1;Sizing.Apply(root,505,960);Check(ReferenceEquals(e,Element(root)),"existing provider reused");Check(e.enabled&&!e.ignoreLayout,"included in native layout");Eq(e.preferredHeight,960,"obsolete height replaced");Eq(e.preferredWidth,505,"obsolete width replaced");Eq(e.flexibleWidth,0,"no forced horizontal stretch");Eq(e.flexibleHeight,0,"no forced vertical stretch");Check(e.layoutPriority>0,"explicit metrics override generic layout provider");});
Run("Repeated opening and smaller bags leave no accumulated bounds",()=>{var root=Rect();Sizing.Apply(root,505,960);Sizing.Apply(root,505,960);Sizing.Apply(root,190,127);Eq(root.Height,127,"root shrinks exactly");Eq(root.Width,190,"root width shrinks exactly");Eq(PreferredHeight(root),127,"parent no longer reserves old bag height");Eq(Element(root).preferredWidth,190,"no stale preferred width");Check(root.gameObject.Components.OfType<LayoutElement>().Count()==1,"one provider only");});
Run("Stretch anchors report physical bounds instead of adding parent dimensions",()=>{var parent=Rect(600,1000);var root=Rect(0,0,parent);root.anchorMax=new(1,1);Sizing.Apply(root,442,834);Eq(root.Width,442,"width independent of parent stretch");Eq(root.Height,834,"height independent of parent stretch");Eq(root.sizeDelta.x,-158,"correct horizontal size delta");Eq(root.sizeDelta.y,-166,"correct vertical size delta");});
Run("Plain wrappers, inventory rows and scroll content all get a rebuild request",()=>{var beyond=Rect();var canvas=Rect(1000,1000,beyond);canvas.gameObject.AddComponent(typeof(Canvas));var scroll=Rect(600,1000,canvas);var row=Rect(600,168,scroll);var plain=Rect(0,0,row);var root=Rect(0,0,plain);Sizing.Apply(root,442,834);foreach(var r in new[]{root,plain,row,scroll,canvas})Check(LayoutRebuilder.Dirty.Contains(r),"ancestor queued");Check(!LayoutRebuilder.Dirty.Contains(beyond),"stops at owning canvas");var before=168f;var after=LayoutRebuilder.Dirty.Contains(row)?Math.Max(before,PreferredHeight(root)):before;Eq(after,834,"native row can reserve actual height");Eq(after+8+190,1032,"scroll content includes bag, gap and pouch");});
Run("Standalone bag windows receive complete background and frame dimensions",()=>{var window=Rect();var root=Rect(0,0,window);Sizing.Apply(root,568,897);var backgroundWidth=Element(root).preferredWidth+16;var backgroundHeight=PreferredHeight(root)+36+16;Eq(backgroundWidth,584,"window encloses every column");Eq(backgroundHeight,949,"window includes title, pockets and padding");Check(LayoutRebuilder.Dirty.Contains(window),"window layout is queued");});
Run("Objects without a canvas still resize and queue their complete parent chain",()=>{var parent=Rect();var root=Rect(0,0,parent);Sizing.Apply(root,127,253);Check(LayoutRebuilder.Dirty.SetEquals(new[]{root,parent}),"detached hierarchy handled");Eq(PreferredHeight(root),253,"detached provider reports height");});
Console.WriteLine($"Backpack layout sizing: {cases-failures}/{cases} cases passed; {checks} assertions; {failures} failures.");return failures==0?0:1;
